@Test
void testFileReadFailure() {
    FileService service = new FileService(mockChannel);
    when(mockChannel.read(any(ByteBuffer.class))).thenThrow(new IOException("Disk failure"));

    IOException exception = assertThrows(IOException.class, () -> service.processData());
    assertEquals("Disk failure", exception.getMessage());
    verify(mockChannel, times(1)).close();
}
